import os
import re
from collections import Counter

import pandas as pd
from fastapi import FastAPI, HTTPException
from fastapi.staticfiles import StaticFiles
from fastapi.middleware.cors import CORSMiddleware
from datasets import load_dataset
import uvicorn

app = FastAPI(title="Glint Research Discord Viewer")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

HF_TOKEN = os.getenv("HF_TOKEN")
DATASET_REPO = "Glint-Research/GlintResearchDiscordChats"

print("Loading dataset from Hugging Face...")
try:
    ds = load_dataset(DATASET_REPO, token=HF_TOKEN, split="train")
    df = ds.to_pandas()
    df["timestamp_parsed"] = pd.to_datetime(df["timestamp"], format='ISO8601')
    df = df.sort_values("timestamp_parsed").reset_index(drop=True)
    df["content"] = df["content"].fillna("")
    print(f"Loaded {len(df)} messages successfully!")
except Exception as e:
    print(f"Error loading dataset: {e}")
    df = pd.DataFrame(columns=['channel_id', 'channel_name', 'guild_id', 'message_id', 'author', 'content', 'timestamp'])
    df["timestamp_parsed"] = pd.to_datetime(df["timestamp"], errors="coerce")

# ---------------------------------------------------------------------------
# Channel index
# ---------------------------------------------------------------------------
channel_stats = df.groupby("channel_id").agg(
    channel_name=("channel_name", "first"),
    message_count=("message_id", "count")
).reset_index()
channel_stats = channel_stats.sort_values("message_count", ascending=False)
channels_list = channel_stats.to_dict(orient="records")


def categorize_channels(channels):
    categories = {
        "INFORMATION": [],
        "GENERAL": [],
        "DEVELOPMENT": [],
        "BOTS & TOOLS": [],
        "TICKETS & HELP": [],
        "MISC": []
    }
    for ch in channels:
        name = ch["channel_name"].lower()
        ch_info = {"id": ch["channel_id"], "name": ch["channel_name"], "count": int(ch["message_count"])}
        if any(kw in name for kw in ["rules", "announce", "welcome", "verify", "roles", "status", "legal", "documentation"]):
            categories["INFORMATION"].append(ch_info)
        elif any(kw in name for kw in ["general", "lobby", "chat", "off-topic", "meme", "funi", "quote", "intro", "drama", "sh1t", "random", "universe"]):
            categories["GENERAL"].append(ch_info)
        elif any(kw in name for kw in ["shard", "project", "drop", "hackathon", "sideproject", "leaderboard", "qwen", "gpt", "train"]):
            categories["DEVELOPMENT"].append(ch_info)
        elif any(kw in name for kw in ["bot-test", "bot-commands", "bot-meta", "discord-bots", "bot"]):
            categories["BOTS & TOOLS"].append(ch_info)
        elif any(kw in name for kw in ["help", "ticket", "log"]):
            categories["TICKETS & HELP"].append(ch_info)
        else:
            categories["MISC"].append(ch_info)
    return {k: v for k, v in categories.items() if v}


categorized_channels = categorize_channels(channels_list)

# ---------------------------------------------------------------------------
# User index
# ---------------------------------------------------------------------------
user_counts = df["author"].value_counts() if len(df) else pd.Series(dtype=int)
users_list = [{"name": str(k), "count": int(v)} for k, v in user_counts.items()]


@app.get("/api/channels")
def get_channels():
    return {
        "categories": categorized_channels,
        "total_messages": len(df),
        "total_channels": len(channels_list)
    }


@app.get("/api/users")
def get_users():
    return {"users": users_list, "total": len(users_list)}


def row_to_msg(row, include_channel_name=False):
    msg = {
        "message_id": str(row["message_id"]),
        "author": str(row["author"]),
        "content": str(row["content"]),
        "timestamp": str(row["timestamp"]),
        "channel_id": str(row["channel_id"]),
    }
    if include_channel_name:
        msg["channel_name"] = str(row["channel_name"])
    return msg


@app.get("/api/messages")
def get_messages(channel_id: str, query: str = None, limit: int = 100, offset: int = None):
    channel_df = df[df["channel_id"] == channel_id]
    if channel_df.empty:
        return {"messages": [], "total": 0, "channel_name": ""}

    if query:
        channel_df = channel_df[channel_df["content"].str.contains(query, case=False, na=False, regex=False)]

    total_count = len(channel_df)
    if offset is None:
        offset = max(0, total_count - limit)
    else:
        offset = max(0, min(offset, max(total_count - 1, 0)))

    sliced_df = channel_df.iloc[offset: offset + limit]
    messages = [row_to_msg(row) for _, row in sliced_df.iterrows()]

    return {
        "messages": messages,
        "total": total_count,
        "offset": offset,
        "limit": limit,
        "channel_name": str(df[df["channel_id"] == channel_id].iloc[0]["channel_name"])
    }


@app.get("/api/search")
def search_all_channels(query: str, author: str = None, limit: int = 50, offset: int = 0):
    if not query or len(query) < 2:
        return {"messages": [], "total": 0, "offset": 0, "limit": limit}

    search_df = df
    if author and author != "__all__":
        search_df = search_df[search_df["author"] == author]

    search_df = search_df[search_df["content"].str.contains(query, case=False, na=False, regex=False)]
    total_count = len(search_df)
    # Newest first for search results
    sliced_df = search_df.iloc[::-1].iloc[offset: offset + limit]

    messages = [row_to_msg(row, include_channel_name=True) for _, row in sliced_df.iterrows()]
    return {"messages": messages, "total": total_count, "offset": offset, "limit": limit}


@app.get("/api/message_context")
def get_message_context(message_id: str, limit: int = 100):
    row = df[df["message_id"].astype(str) == str(message_id)]
    if row.empty:
        raise HTTPException(status_code=404, detail="Message not found")

    ch_id = str(row.iloc[0]["channel_id"])
    channel_df = df[df["channel_id"] == ch_id].reset_index(drop=True)

    try:
        msg_idx = channel_df[channel_df["message_id"].astype(str) == str(message_id)].index[0]
    except Exception:
        raise HTTPException(status_code=404, detail="Message index not found in channel")

    offset = max(0, msg_idx - limit // 2)
    if offset + limit > len(channel_df):
        offset = max(0, len(channel_df) - limit)

    sliced_df = channel_df.iloc[offset: offset + limit]
    messages = [row_to_msg(r) for _, r in sliced_df.iterrows()]

    return {
        "messages": messages,
        "total": len(channel_df),
        "offset": offset,
        "limit": limit,
        "channel_name": str(channel_df.iloc[0]["channel_name"]),
        "channel_id": ch_id,
        "target_message_id": message_id
    }


@app.get("/api/stats")
def get_stats():
    total_msgs = len(df)
    unique_authors = int(df["author"].nunique()) if total_msgs > 0 else 0
    top_authors = df["author"].value_counts().head(5).to_dict() if total_msgs > 0 else {}
    return {
        "total_messages": total_msgs,
        "unique_users": unique_authors,
        "top_contributors": [{"name": k, "count": int(v)} for k, v in top_authors.items()]
    }


# ---------------------------------------------------------------------------
# Fun facts (n-gram / letter / emoji stats)
# ---------------------------------------------------------------------------
WORD_RE = re.compile(r"[a-z][a-z']*")
URL_RE = re.compile(r"https?://\S+")
MENTION_RE = re.compile(r"<a?:\w+:\d+>|<[@#&!]+\d+>")
EMOJI_RE = re.compile(
    "[\U0001F300-\U0001FAFF\U00002600-\U000027BF\U0001F000-\U0001F0FF\U00002190-\U000021FF\U00002B00-\U00002BFF]"
)

STOPWORDS = {
    "the", "a", "an", "i", "to", "and", "is", "it", "of", "in", "that", "you",
    "for", "on", "this", "be", "with", "was", "are", "but", "not", "have",
    "so", "if", "or", "my", "at", "me", "we", "do", "can", "its", "it's",
    "just", "like", "what", "im", "i'm", "dont", "don't", "as", "no", "yes",
    "he", "she", "they", "them", "his", "her", "your", "from", "by", "how",
    "all", "will", "would", "there", "their", "what", "when", "who", "get",
    "u", "ur", "its", "thats", "that's", "has", "had", "did", "were", "been",
}

_funfacts_cache = {}


def clean_text(text: str) -> str:
    text = URL_RE.sub(" ", text)
    text = MENTION_RE.sub(" ", text)
    return text.lower()


def compute_funfacts(author: str):
    key = author or "__all__"
    if key in _funfacts_cache:
        return _funfacts_cache[key]

    sub = df if key == "__all__" else df[df["author"] == author]
    if sub.empty:
        raise HTTPException(status_code=404, detail="User not found")

    words_counter = Counter()
    bigram_counter = Counter()
    trigram_counter = Counter()
    letter_counter = Counter()
    emoji_counter = Counter()

    total_words = 0
    total_chars = 0
    caps_msgs = 0
    question_msgs = 0
    exclaim_msgs = 0
    longest_msg = ""

    contents = sub["content"].astype(str)
    for raw in contents:
        if not raw:
            continue
        total_chars += len(raw)
        stripped = raw.strip()
        if len(stripped) > 3 and stripped.isupper():
            caps_msgs += 1
        if "?" in raw:
            question_msgs += 1
        if "!" in raw:
            exclaim_msgs += 1
        if len(raw) > len(longest_msg):
            longest_msg = raw

        emoji_counter.update(EMOJI_RE.findall(raw))

        cleaned = clean_text(raw)
        tokens = WORD_RE.findall(cleaned)
        total_words += len(tokens)
        for t in tokens:
            letter_counter.update(c for c in t if c.isalpha())
        words_counter.update(t for t in tokens if t not in STOPWORDS and len(t) > 1)
        for i in range(len(tokens) - 1):
            bigram_counter[tokens[i] + " " + tokens[i + 1]] += 1
        for i in range(len(tokens) - 2):
            trigram_counter[tokens[i] + " " + tokens[i + 1] + " " + tokens[i + 2]] += 1

    msg_count = len(sub)
    hours = sub["timestamp_parsed"].dt.hour.value_counts()
    days = sub["timestamp_parsed"].dt.day_name().value_counts()
    fav_channels = sub["channel_name"].value_counts().head(5)

    def top(counter, n=8):
        return [{"value": k, "count": int(v)} for k, v in counter.most_common(n)]

    result = {
        "author": key,
        "message_count": msg_count,
        "total_words": total_words,
        "total_chars": total_chars,
        "avg_words_per_message": round(total_words / msg_count, 1) if msg_count else 0,
        "avg_chars_per_message": round(total_chars / msg_count, 1) if msg_count else 0,
        "caps_messages": caps_msgs,
        "question_messages": question_msgs,
        "exclaim_messages": exclaim_msgs,
        "longest_message": longest_msg[:500],
        "longest_message_length": len(longest_msg),
        "top_words": top(words_counter, 10),
        "top_bigrams": top(bigram_counter, 10),
        "top_trigrams": top(trigram_counter, 10),
        "top_letters": top(letter_counter, 10),
        "top_emoji": top(emoji_counter, 10),
        "busiest_hour": int(hours.idxmax()) if len(hours) else None,
        "hour_histogram": {int(h): int(c) for h, c in hours.items()},
        "busiest_day": str(days.idxmax()) if len(days) else None,
        "favorite_channels": [{"value": str(k), "count": int(v)} for k, v in fav_channels.items()],
        "first_message_at": str(sub["timestamp_parsed"].min()),
        "last_message_at": str(sub["timestamp_parsed"].max()),
    }

    _funfacts_cache[key] = result
    return result


@app.get("/api/funfacts")
def get_funfacts(author: str = "__all__"):
    return compute_funfacts(author)


app.mount("/", StaticFiles(directory="static", html=True), name="static")

if __name__ == "__main__":
    uvicorn.run("app:app", host="0.0.0.0", port=7860, reload=True)

